/**
 * Spreads the tax due on a rate group over its lines. Each line gets the whole
 * units of its own exact tax, and the units left over go to the lines with the
 * biggest fractions, so the lines add up to `due` and none is more than a unit
 * from its exact tax. A group that nets to a negative is worked as its mirror.
 */
function spreadTax(nets, rateBps, due) {
  if (due < 0) return spreadTax(nets.map((net) => -net), rateBps, -due).map((tax) => -tax || 0);
  const scale = BigInt(BASIS_POINTS);
