    const exact = BigInt(net) * BigInt(rateBps);
    let whole = exact / scale;
    if (exact % scale < 0n) whole -= 1n;
    return { position, whole, fraction: exact - whole * scale };
  });
  let spare = BigInt(due) - parts.reduce((sum, part) => sum + part.whole, 0n);
  const byFraction = [...parts].sort((a, b) => {
    if (a.fraction === b.fraction) return a.position - b.position;
    return a.fraction > b.fraction ? -1 : 1;
  });
  for (const part of byFraction) {
    if (spare <= 0n) break;
    part.whole += 1n;
    spare -= 1n;
  }
  return parts.map((part) => Number(part.whole));
