import assert from 'node:assert/strict';
import test from 'node:test';

import {
  allocate,
  billingPeriods,
  buildInvoice,
  createBook,
  createCatalog,
  defineCoupon,
  definePlan,
  defineTaxTable,
  formatAmount,
  parseAmount,
} from '../src/index.mjs';

test('a month-end anchor returns to the 31st after a short month', () => {
  const ends = billingPeriods('2023-01-31', 1, 4).map((period) => period.end);
  assert.deepEqual(ends, ['2023-02-28', '2023-03-31', '2023-04-30', '2023-05-31']);
});

test('currencies with other decimals parse and format correctly', () => {
  assert.equal(parseAmount('2900', 'JPY'), 2900);
  assert.equal(parseAmount('29.123', 'KWD'), 29123);
  assert.throws(() => parseAmount('29.5', 'JPY'), RangeError);
  assert.equal(formatAmount(29123, 'KWD'), 'KWD 29.123');
  assert.equal(formatAmount(2900, 'JPY'), 'JPY 2,900');
});

test('allocate is fair and mirrors for negative amounts', () => {
  assert.deepEqual(allocate(5, [1, 0, 1]), [3, 0, 2]);
  assert.deepEqual(allocate(-5, [1, 0, 1]), [-3, 0, -2]);
});

test('line tax adds up to the tax due per rate', () => {
  const invoice = buildInvoice({
    number: 'INV-1',
    customerId: 'c',
    currency: 'USD',
    issueDate: '2024-01-01',
    lines: [1, 2, 3].map(() => ({ description: 'x', unitAmount: 5, taxRateBps: 1000 })),
  });
  assert.equal(invoice.lines.reduce((sum, line) => sum + line.tax, 0), invoice.taxTotal);
});

test('account credit settles an invoice without changing its charges', () => {
  const plan = definePlan({ code: 'p', prices: { USD: '100.00' } });
  const book = createBook({
    catalog: createCatalog([plan]),
    taxTable: defineTaxTable({ NL: [{ from: '2000-01-01', rateBps: 2000 }] }),
  });
  book.grantAccountCredit('c', 'USD', { amount: 3000, date: '2024-01-01' });
  const invoice = book.subscribe({
    id: 's', customerId: 'c', planCode: 'p', currency: 'USD', anchor: '2024-01-01', region: 'NL',
  });
  assert.equal(invoice.taxTotal, 2000);
  assert.equal(invoice.total, 12000);
  assert.equal(invoice.creditApplied, 3000);
  assert.equal(invoice.amountDue, 9000);
  assert.equal(book.balanceOf(invoice.number), 9000);
  assert.deepEqual(book.unbalancedJournalEntries(), []);
});

test('a discounted plan change credits no more than was paid', () => {
  const plan = definePlan({ code: 'a', prices: { USD: '29.00' } });
  const bigger = definePlan({ code: 'b', prices: { USD: '58.00' } });
  const book = createBook({
    catalog: createCatalog([plan, bigger], [defineCoupon({ code: 'H', percentBps: 1000 })]),
  });
  book.subscribe({
    id: 's', customerId: 'c', planCode: 'a', currency: 'USD', anchor: '2024-02-01', couponCode: 'H',
  });
  const change = book.changePlan('s', { date: '2024-02-16', planCode: 'b' });
  assert.equal(change.lines[0].net, -1260);
});

test('staged refunds never exceed what was charged and end at zero', () => {
  const plan = definePlan({ code: 'p', prices: { USD: '100.00' } });
  const book = createBook({
    catalog: createCatalog([plan]),
    taxTable: defineTaxTable({ NL: [{ from: '2000-01-01', rateBps: 2100 }] }),
  });
  const invoice = book.subscribe({
    id: 's', customerId: 'c', planCode: 'p', currency: 'USD', anchor: '2024-01-01', region: 'NL',
  });
  book.pay(invoice.number, { amount: invoice.total, date: '2024-01-02' });
  for (const amount of [3333, 3333]) {
    book.creditInvoice(invoice.number, { date: '2024-01-05', lines: [{ lineIndex: 0, amount }] });
  }
  const last = book.creditInvoice(invoice.number, { date: '2024-01-06' });
  assert.equal(last.lines[0].net, 3334);
  const notes = book.notes();
  assert.equal(notes.reduce((sum, note) => sum + note.taxTotal, 0), invoice.taxTotal);
  assert.equal(notes.reduce((sum, note) => sum + note.settlement.refunded, 0), invoice.total);
  assert.equal(book.balanceOf(invoice.number), 0);
  assert.deepEqual(book.unbalancedJournalEntries(), []);
});
'@ | Set-Content test/regression-cases.mjs
node --test --test-isolation=none "test/*.mjs" 2>&1 | Select-String "^(✖|ℹ (pass|fail))|^test at|Error|actual|expected"

